  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Record C01 reports absolute oral bioavailability of 13.8% in healthy human volunteers after a single 0.25 g oral dose, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Record C14 reports absolute oral bioavailability of revefenacin following oral administration is <3% in healthy volunteers and COPD patients, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Record C38 reports absolute bioavailability of a single 75-mg oral dose of aliskiren is 2.6% in healthy subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred quantitative absolute bioavailability records are below 20% (range ~0.3–13.8%), with the highest-transfer record at 13.8%; therefore low bioavailability is supported.",
  "evidence_gaps": [
    "No retrieved evidence supports F >= 20%; all quantitative records are below threshold.",
    "Some records are qualitative or report systemic availability rather than absolute F; numeric absolute records were prioritized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

